#define _CRT_SECURE_NO_WARNINGS

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <memory.h>

using namespace std;
#define NUM_ALPHABET 26

int N;
vector<string> input;
vector<int> order;
int adj[NUM_ALPHABET][NUM_ALPHABET];
vector<int > indegree, outdegree;
vector<string > graph[NUM_ALPHABET][NUM_ALPHABET];


void makeGraph()
{
	memset(adj, 0, sizeof(adj));

	for (int i = 0; i < NUM_ALPHABET; i++)
	{
		for (int j = 0; j < NUM_ALPHABET; j++)
		{
			graph[i][j].clear();
		}
	}

	indegree = outdegree = vector<int >(26, 0);

	for (int i = 0; i < N; i++)
	{
		int a = input[i][0] - 'a';
		int b = input[i][input[i].size()-1] - 'a';

		graph[a][b].push_back(input[i]);

		adj[a][b]++;

		outdegree[a]++;
		indegree[b]++;
	}
}

void getEulerCircit(int src, vector<int >& circuit)
{
	for (int des = 0; des < NUM_ALPHABET; des++)
	{
		while (adj[src][des])
		{
			adj[src][des]--;
			getEulerCircit(des,circuit);
		}
	}

	circuit.push_back(src);
}

vector<int> getEulerTrailOrCircit()
{
	vector<int > circuit;

	for (int i = 0; i < NUM_ALPHABET; i++)
	{
		if (outdegree[i] == indegree[i] + 1)
		{
			getEulerCircit(i, circuit);
			return circuit;
		}
	}

	for (int i = 0; i < NUM_ALPHABET; i++)
	{
		if (outdegree[i])
		{
			getEulerCircit(i, circuit);
			return circuit;
		}
	}

	return circuit;
}

bool checkEuiler()
{
	int plus1 = 0, minus1 = 0;

	for (int i = 0; i < NUM_ALPHABET; i++)
	{
		int delta = outdegree[i] - indegree[i];

		if (delta < -1 || 1 < delta)
		{
			return false;
		}

		if (delta == 1)
		{
			plus1++;
		}

		if (delta == -1)
		{
			minus1++;
		}
	}

	return (plus1 == 1 && minus1 == 1) || (plus1 == 0 && minus1 == 0);
}

string solve()
{
	makeGraph();

	if (!checkEuiler())
	{
		return "IMPOSSIBLE";
	}

	vector<int> circuit = getEulerTrailOrCircit();

	if (circuit.size() != input.size() + 1)
	{
		return "IMPOSSIBLE";
	}

	reverse(circuit.begin(), circuit.end());

	string ret;

	for (int i = 1; i < circuit.size(); i++)
	{
		int a = circuit[i - 1], b = circuit[i];

		if (ret.size())
		{
			ret += " ";
		}

		ret += graph[a][b].back();

		graph[a][b].pop_back();
	}

	return ret;
}

int main(int argc, char** argv)
{
	int tc, T;

#ifdef _WIN32
	freopen("WORDCHAIN.txt", "r", stdin);
#endif

	cin >> T;
	for (tc = 0; tc < T; tc++)
	{
		cin >> N;

		input.clear();

		for (int i = 0; i < N; i++)
		{
			string s;
			cin >> s;
			input.push_back(s);
		}
		cout << solve() << endl;
	}

	return 0;
}

package main

import (
	"fmt"
	"math"
	"math/big"
	"math/rand"
	"os"
	"strconv"
	"time"
)

var (
	eta int 	// 安全参数η
	p uint64	// 对称密钥
	q *big.Int	// 参数
)

func main()  {
	if len(os.Args) <= 1 {
		panic("Please input parameters η")
	}
	//	为了防止q的溢出，q是64位则η<=4,q是256位则η<=6 (η^3 < 位数)
	eta, _ = strconv.Atoi(os.Args[1]) 		//  测试得出： η >= 9 加法、乘法计算稳定
	fmt.Println("η = ", eta)
	fmt.Printf("p range is [%d, %d)\n", int(math.Pow(float64(2), float64(eta-1))), int(math.Pow(float64(2), float64(eta))))
	for i := 0; i < 100; i++ {
		rand.Seed(time.Now().UnixNano() + int64(i))
		// 生成密钥
		fmt.Println("p = ", genKey_p())
		// 生成参数q
		fmt.Printf("q = %d\n", genPara_q())
		//genPara_q()
		// 加密测试
		m0, m1 := uint(0), uint(1)
		fmt.Printf("m0 = %d, m1 = %d\n", m0, m1)
		c0 := Encrypto(m0)
		c1 := Encrypto(m1)
		//fmt.Printf("c0 = %d, c1 = %d\n", c0, c1)
		// 解密
		n0, n1 := Decrypto(c0), Decrypto(c1)
		fmt.Printf("解密结果：n0 = %d, n1 = %d\n", n0, n1)
		// 评估
		// 加法测试
		fmt.Printf("加法测试：%d + %d , %v\n", m0, m1, EvaluateAdd(m0, m1, c0, c1))
		fmt.Printf("加法测试：%d + %d , %v\n", m0, m0, EvaluateAdd(m0, m0, c0, c0))
		fmt.Printf("加法测试：%d + %d , %v\n", m1, m1, EvaluateAdd(m1, m1, c1, c1))
		fmt.Printf("加法测试：%d + %d , %v\n", m1, m0, EvaluateAdd(m1, m0, c1, c0))
		fmt.Println("==============================================")
		// 乘法测试
		fmt.Printf("乘法测试：%d * %d , %v\n", m0, m1, EvaluateMul(m0, m1, c0, c1))
		fmt.Printf("乘法测试：%d * %d , %v\n", m0, m0, EvaluateMul(m0, m0, c0, c0))
		fmt.Printf("乘法测试：%d * %d , %v\n", m1, m1, EvaluateMul(m1, m1, c1, c1))
		fmt.Printf("乘法测试：%d * %d , %v\n", m1, m0, EvaluateMul(m1, m0, c1, c0))
		fmt.Println("==============================================")
	}
}

func genKey_p() uint64 {
	// p ∈ [2^(η−1), 2^η) and odd
	for {
		randomP := int(math.Pow(float64(2), float64(eta-1))) + rand.Intn(int(math.Pow(float64(2), float64(eta-1))))
		if randomP % 2 == 1 {
			p = uint64(randomP)
			return p
		}
	}
}

func genPara_r() int64 {
	// |2r| < p/2
	//  r ≈ 2^(√η)
	goal := int(math.Pow(2, math.Sqrt(float64(eta))))
	r := 2
	randr := goal - r + 2 * rand.Intn(r)
	for int(math.Abs(float64(2 * randr))) >= int(p) / 2 {
		rand.Seed(time.Now().UnixNano())
		randr = goal - r + 2 * rand.Intn(r)
	}
	//fmt.Println("r = ", randr)
	return int64(randr)
}

func genPara_q() *big.Int {
	// q ≈ 2^(η^3)
	goal := big.NewInt(1)
	for i := 0; i < int(math.Pow(float64(eta), 3)); i++ {
		goal.Mul(goal, big.NewInt(2))
	}
	r := 100
	goal.Sub(goal, big.NewInt(int64(r)))
	goal.Add(goal, big.NewInt(int64(2 * rand.Intn(r))))
	q = goal
	return q
}

func Encrypto(m uint) *big.Int {
	r := genPara_r()
	c := big.NewInt(int64(m) + 2*r)
	mul := q.Mul(q, big.NewInt(int64(p)))
	c.Add(c, mul)
	return c
}

func Decrypto(c *big.Int) uint64 {
	mod := &big.Int{}
	mod = mod.Mod(c, big.NewInt(int64(p)))
	mod.Mod(mod, big.NewInt(2))
	return mod.Uint64()
}

func EvaluateAdd(m0, m1 uint, c0, c1 *big.Int) bool {
	c := &big.Int{}
	c.Add(c0, c1)
	n := Decrypto(c)
	if m0 == 1 && m1 == 1 {
		return n == 0
	}
	return n == uint64(m0 + m1)
}

func EvaluateMul(m0, m1 uint, c0, c1 *big.Int) bool {
	c := &big.Int{}
	c.Mul(c0, c1)
	n := Decrypto(c)
	return n == uint64(m0 * m1)
}

