	GPIO_PORTE_DATA_R ^= 0x02;	// toggle PE1
}

// Subroutine to add a delay
// Inputs: number of 1ms delays
// Output: None
// Notes: assumes 80 MHz clock
void Delayms(unsigned long ms){
	unsigned long delay;
	while (ms>0){
		delay = 16000;
		while (delay > 0){
			delay -= 1;
		}
		ms -= 1;
	}
}

