            visited[i][j] = false;
        }


    for (int i = 1; i <= N; i++)
        for (int j = 1; j <= N; j++){
            if (visited[i][j] == false && map[i][j] == 1){
                dfs(i, j);
                counter++;
            }
        }


    getMinimumDistance();

    return 0;

}

