use x86_64::instructions::interrupts;

static WAKER: AtomicWaker = AtomicWaker::new();
static SCANCODE_QUEUE: OnceCell<ArrayQueue<u8>> = OnceCell::uninit();

pub async fn print_keypresses() {
    // creates new queue for keys
    let mut scancodes = ScancodeStream::new();
    let mut keyboard = Keyboard::new(layouts::Us104Key, ScancodeSet1,
        HandleControl::Ignore);

    // waits for next keypress then hands it over to the KEYBOARD_ROUTER to handle
    while let Some(scancode) = scancodes.next().await {
        interrupts::without_interrupts(|| {
            KEYBOARD_ROUTER.lock().handle_scancode(scancode,&mut keyboard);
        });
    }
}

// adds new keypresses to the queue to be dealt with
pub(crate) fn add_scancode(scancode: u8) {
    if let Ok(queue) = SCANCODE_QUEUE.try_get() {
        if queue.push(scancode).is_err() {
            println!("WARNING: scancode queue full; dropping keyboard input");
        }else{
            // after pusing the scancode to queue the waker will notify the executor
            WAKER.wake();
        }
    } else {
        println!("WARNING: scancode queue uninitialized");
    }
}

pub struct ScancodeStream {
    _private: (),
}

impl Default for ScancodeStream {
    fn default() -> ScancodeStream {
        ScancodeStream::new()
    }
}

// initializes scancode stream and returns an error if it's tried again
impl ScancodeStream {
    pub fn new() -> Self {
        SCANCODE_QUEUE.try_init_once(|| ArrayQueue::new(100))
            .expect("ScancodeStream::new should only be called once");
        ScancodeStream { _private: () }
    }
}

impl Stream for ScancodeStream {
    type Item = u8;

    // polls the next item in the queue
    fn poll_next(self: Pin<&mut Self>, cx: &mut Context) -> Poll<Option<u8>> {
        let queue = SCANCODE_QUEUE
            .try_get()
            .expect("scancode queue not initialized");

        // immediately tries to poll from the queue
        if let Ok(scancode) = queue.pop() {
            return Poll::Ready(Some(scancode));
        }

        // if the item from queue is pending it gets a waker
        WAKER.register(&cx.waker());
        match queue.pop() {
            Ok(scancode) => {
                WAKER.take();
                Poll::Ready(Some(scancode))
            }
            Err(crossbeam_queue::PopError) => Poll::Pending,
        }
    }
}

use crate::never::Never;
use core::pin::Pin;
use futures_core::future::{FusedFuture, Future};
use futures_core::task::{self, Poll};
use pin_utils::unsafe_pinned;

/// Future for the [`never_error`](super::FutureExt::never_error) combinator.
#[derive(Debug)]
#[must_use = "futures do nothing unless you `.await` or poll them"]
pub struct NeverError<Fut> {
    future: Fut,
}

impl<Fut> NeverError<Fut> {
    unsafe_pinned!(future: Fut);

    pub(super) fn new(future: Fut) -> NeverError<Fut> {
        NeverError { future }
    }
}

impl<Fut: Unpin> Unpin for NeverError<Fut> {}

impl<Fut: FusedFuture> FusedFuture for NeverError<Fut> {
    fn is_terminated(&self) -> bool { self.future.is_terminated() }
}

impl<Fut, T> Future for NeverError<Fut>
    where Fut: Future<Output = T>,
{
    type Output = Result<T, Never>;

    fn poll(self: Pin<&mut Self>, cx: &mut task::Context<'_>) -> Poll<Self::Output> {
        self.future().poll(cx).map(Ok)
    }
}

use alloc::vec::Vec;
use core::convert::TryInto;

use crate::aes;
use crate::Error;

/// Encrypt a message using AES-128-ECB
pub fn encrypt(plaintext: &[u8], key: &[u8; aes::KEY_LEN_128]) -> Result<Vec<u8>, Error> {
    let len = plaintext.len();
    if len % aes::BLOCK_LEN != 0 {
        return Err(Error::InvalidLength);
    }

    let mut res = Vec::with_capacity(len);
    for block in plaintext.chunks_exact(aes::BLOCK_LEN) {
        res.extend_from_slice(&aes::aes_128(block.try_into().unwrap(), &key)[..]);
    }

    Ok(res)
}

/// Decrypt a ciphertext using AES-128-ECB
pub fn decrypt(ciphertext: &[u8], key: &[u8; aes::KEY_LEN_128]) -> Result<Vec<u8>, Error> {
    let len = ciphertext.len();
    if len % aes::BLOCK_LEN != 0 {
        return Err(Error::InvalidLength);
    }

    let mut res = Vec::with_capacity(len);
    for block in ciphertext.chunks_exact(aes::BLOCK_LEN) {
        res.extend_from_slice(&aes::aes_inv_128(block.try_into().unwrap(), &key)[..]);
    }

    Ok(res)
}

